"""Keep short codes and their target URLs in memory."""

from __future__ import annotations

from urllib.parse import urlsplit

from shortener.codes import encode


class LinkStore:
    """Maps short codes to URLs; the same URL always gets the same code."""

    def __init__(self, start: int = 1000) -> None:
        self._next = start
        self._by_code: dict[str, str] = {}
        self._by_url: dict[str, str] = {}

    def shorten(self, url: str) -> str:
        """Return the code for url, creating one if needed."""
        parts = urlsplit(url)
        if parts.scheme not in ("http", "https") or not parts.netloc:
            raise ValueError(f"not an http(s) URL: {url!r}")
        if url in self._by_url:
            return self._by_url[url]
        code = encode(self._next)
        self._next += 1
        self._by_code[code] = url
        self._by_url[url] = code
        return code

    def expand(self, code: str) -> str:
        """Return the URL stored for code; raises KeyError for unknown codes."""
        return self._by_code[code]

    def count(self) -> int:
        """Number of stored links."""
        return len(self._by_code)

    def delete(self, code: str) -> None:
        """Forget a code and its URL."""
        url = self._by_code.pop(code)
        del self._by_url[url]

    def urls(self) -> list[str]:
        """Stored URLs in alphabetical order."""
        return sorted(self._by_url)

